<?php require __DIR__.'/../config/db.php';require __DIR__.'/../includes/functions.php';require_admin();$event=active_event($pdo);if(!$event){flash('error','กรุณาสร้างและเปิดใช้งานงานก่อน');header('Location: events.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$name=trim($_POST['name']??'');if($name!==''){$v=[$name,isset($_POST['requires_org_name'])?1:0,isset($_POST['requires_status_field'])?1:0,(int)($_POST['sort_order']??0)];if($id){$v[]=$id;$q='UPDATE participant_types SET name=?,requires_org_name=?,requires_status_field=?,sort_order=? WHERE id=? AND event_id=?';$v[]=$event['id'];}else{$q='INSERT INTO participant_types(name,requires_org_name,requires_status_field,sort_order,event_id) VALUES(?,?,?,?,?)';$v[]=$event['id'];}$pdo->prepare($q)->execute($v);flash('success','บันทึกประเภทเรียบร้อย');}}elseif($action==='delete'&&($id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT))){$pdo->prepare('DELETE FROM participant_types WHERE id=? AND event_id=?')->execute([$id,$event['id']]);flash('success','ลบประเภทเรียบร้อย');}header('Location: participant_types.php');exit;}$edit=null;if($id=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)){$q=$pdo->prepare('SELECT * FROM participant_types WHERE id=? AND event_id=?');$q->execute([$id,$event['id']]);$edit=$q->fetch();}$q=$pdo->prepare('SELECT * FROM participant_types WHERE event_id=? ORDER BY sort_order,id');$q->execute([$event['id']]);$rows=$q->fetchAll();$adminTitle='ประเภทผู้เข้าร่วม';$adminPage='types';require __DIR__.'/header.php'; ?>
<div class="admin-panel"><h2><?= $edit?'แก้ไขประเภท':'เพิ่มประเภทผู้เข้าร่วม'?> · <?=e($event['name'])?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0)?>"><div class="field-grid"><div class="field"><label class="field-label">ชื่อประเภท</label><input class="input" name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label class="field-label">ลำดับ</label><input class="input" type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></div></div><label><input type="checkbox" name="requires_org_name" <?=($edit['requires_org_name']??false)?'checked':''?>> บังคับกรอกชื่อส่วนงาน</label> <label><input type="checkbox" name="requires_status_field" <?=($edit['requires_status_field']??false)?'checked':''?>> แสดงข้อมูลสถานภาพและสังกัด</label><div class="actions"><button class="button button-primary">บันทึก</button><?php if($edit):?><a class="button button-outline" href="participant_types.php">ยกเลิก</a><?php endif;?></div></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ชื่อประเภท</th><th>ฟิลด์พิเศษ</th><th>ลำดับ</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?= $r['requires_org_name']?'ส่วนงาน ':''?><?= $r['requires_status_field']?'สถานภาพ':''?></td><td><?=$r['sort_order']?></td><td><div class="inline-form"><a class="button button-outline button-small" href="?edit=<?=$r['id']?>">แก้ไข</a><form method="post" onsubmit="return confirm('ลบประเภทนี้หรือไม่?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button button-danger button-small">ลบ</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/footer.php';
